message.content:
{
  "definition_simple": "物体の内部にある、何もない空のスペース。",
  "definition_standard": "物質の内部にできた、何もない空間や穴のこと。また、転じて実体のない様子を指すこともある。",
  "pos": "名詞",
  "semantic_class": "concrete",
  "sentences": [
    {
      "tier": "T1",
      "japanese": "歯に空洞ができる。",
      "english": "A cavity forms in the tooth."
    },
    {
      "tier": "T1",
      "japanese": "壁の裏に空洞がある。",
      "english": "There is a hollow space behind the wall."
    },
    {
      "tier": "T2",
      "japanese": "木の中に大きな空洞が見つかった。",
      "english": "A large hollow was found inside the tree."
    },
    {
      "tier": "T2",
      "japanese": "地下には自然の空洞が広がっている。",
      "english": "Natural caves and hollows spread underground."
    },
    {
      "tier": "T3",
      "japanese": "地盤沈下により道路の下に空洞ができていた。",
      "english": "A void had formed under the road due to land subsidence."
    },
    {
      "tier": "T4",
      "japanese": "その古い彫刻の内部は空洞の構造になっていた。",
      "english": "The interior of the old sculpture had a hollow structure."
    },
    {
      "tier": "T5",
      "japanese": "心にぽっかりと空洞が開いたような喪失感を覚える。",
      "english": "I feel a sense of loss, as if a void has opened up in my heart."
    },
    {
      "tier": "T6",
      "japanese": "火山活動の名残として溶岩トンネルの空洞があちこちに散在している。",
      "english": "Hollows of lava tubes are scattered here and there as remnants of volcanic activity."
    },
    {
      "tier": "T3",
      "japanese": "コンクリートの柱の内部空洞に補強剤を注入した。",
      "english": "Reinforcing agent was injected into the internal cavity of the concrete pillar."
    },
    {
      "tier": "T5",
      "japanese": "長年連れ添った伴侶を亡くし、胸の空洞を埋めることができない。",
      "english": "Having lost the partner of many years, I cannot fill the void in my chest."
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "primary_collocate": "地下空洞",
  "collocation_distractors": [
    {
      "word": "地下空間",
      "reason": "「地下空間」は人工的・自然的な広いスペース全般を指し、空洞特有の「閉ざされた空間や穴」というニュアンスが薄い。"
    },
    {
      "word": "地底湖",
      "reason": "「地底湖」は水が溜まった場所であり、空間そのものを指す「空洞」とは意味が異なる。"
    },
    {
      "word": "地下茎",
      "reason": "「地下茎」は植物の茎の一部を指す用語であり、空間や穴を表す言葉ではない。"
    }
  ],
  "collocation_wrong_collocate": "空洞現象",
  "cloze_distractors": [
    {
      "word": "空白",
      "reason": "「空白」は時間や書類の書き込みがない部分に使われ、物理的な空間の穴には使わない。"
    },
    {
      "word": "空腹",
      "reason": "「空腹」は胃の中に食べ物がない状態（お腹が空いたこと）を指し、文脈に全く合わない。"
    },
    {
      "word": "虚無",
      "reason": "「虚無」は哲学的な何もない状態やむなさを指す抽象名詞であり、物理的な穴を表す文には入らない。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "私は昨日、新しい空洞を買った。",
      "reason": "「空洞」は物理的な穴や空間のことであり、所有物を購入する対象にはならないため意味的に不自然である。"
    },
    {
      "sentence": "彼らは空洞を早く走るために特訓した。",
      "reason": "「空洞」は走るためのコースや道路ではないため、動詞「走る」の文脈に適合しない。"
    },
    {
      "sentence": "このスープはとても空洞だ。",
      "reason": "「空洞」は味や性質を表す形容動詞ではないため、「～だ」の叙述語として使えない。"
    }
  ],
  "spot_incorrect": {
    "sentence": "古い神社の床下に、大きな空洞を見つけた。",
    "error_description": "文法的な誤りはないが、例文として指定された「壁の裏に空洞がある。」の誤り訂正問題として、助詞の誤用を仕込んだ文「古い神社の床下に、大きな空洞をあった。」を提示する。",
    "corrected": "古い神社の床下に、大きな空洞があった。"
  },
  "word_family_forms": [
    {
      "form": "空洞化",
      "pos": "名詞・サ変動詞",
      "definition": "内部が空洞になること。また、都市の中心部や産業などが衰退して実質が失われること。"
    }
  ],
  "word_family_fake_forms": [
    "空洞的",
    "空洞さ",
    "空洞がる"
  ],
  "syn_ant_candidates": [
    {
      "word": "空隙",
      "type": "synonym"
    },
    {
      "word": "穴",
      "type": "synonym"
    },
    {
      "word": "実質",
      "type": "antonym"
    },
    {
      "word": "充填",
      "type": "antonym"
    }
  ],
  "particle_candidates": [
    {
      "sentence": "壁の裏[ ]空洞がある。",
      "particles": [
        "に",
        "で",
        "を",
        "は"
      ],
      "correct": "に",
      "explanation": "存在を表す動詞「ある」の直前で、存在場所を示すためには格助詞「に」が適切である。"
    }
  ]
}
